def largestNumber(cost: list[int], target: int) -> str:
    NEG = float('-inf')
    # dp[t] = maximum number of digits reachable with total cost exactly t.
    dp = [NEG] * (target + 1)
    dp[0] = 0
    for t in range(1, target + 1):
        for c in cost:
            if t >= c and dp[t - c] + 1 > dp[t]:
                dp[t] = dp[t - c] + 1
    if dp[target] < 0:
        return "0"
    # Greedily take the largest digits first so digits come out descending.
    res = []
    t = target
    for d in range(9, 0, -1):
        c = cost[d - 1]
        while t >= c and dp[t - c] >= 0 and dp[t - c] + 1 == dp[t]:
            res.append(str(d))
            t -= c
    return ''.join(res)
